// GPT-made SVG sprites (assets/gpt, generated by tools/gen_art.mjs with gpt-6.1-sol).
// Heroes are split into layers (back / body / head / weapon) so the rig can animate them; monsters are recoloured per kind.
const BASE = new URL('../assets/gpt/', import.meta.url);
const heroes = new Map();   // class key → { L: {back, body, head, weapon}, pivot: [x, y] }
const mobSvg = new Map();   // slug → svg text
const mobImg = new Map();   // slug|palette → Image, or 1 while loading
let notifyT = 0;
const notify = () => { clearTimeout(notifyT); notifyT = setTimeout(() => window.dispatchEvent(new Event('sxs-art')), 80); };
const toImg = (svg) => new Promise((res) => { const im = new Image(); im.onload = () => res(im); im.onerror = () => res(null); im.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg); });

export async function loadArt() {
  let ids = [];
  try { const r = await fetch(new URL('index.json', BASE)); if (r.ok) ids = await r.json(); } catch (e) { /* art is optional */ }
  await Promise.all(ids.map(async (id) => {
    try {
      const r = await fetch(new URL(id + '.svg', BASE)); if (!r.ok) return;
      const txt = await r.text();
      if (id.startsWith('mob_')) { mobSvg.set(id.slice(4), txt); return; }
      const root = new DOMParser().parseFromString(txt, 'image/svg+xml').documentElement;
      const vb = root.getAttribute('viewBox') || '0 0 200 240', ser = new XMLSerializer();
      const wrap = (inner) => `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${vb}" width="400" height="480">${inner}</svg>`;
      const L = {};
      for (const name of ['back', 'body', 'head', 'weapon']) { const g = root.querySelector('#' + name); L[name] = g ? await toImg(wrap(ser.serializeToString(g))) : null; }
      const wg = root.querySelector('#weapon');
      const pv = ((wg && wg.getAttribute('data-pivot')) || '132,150').split(',').map(Number);
      if (L.body && L.head) heroes.set(id.slice(5), { L, pivot: [pv[0] || 132, pv[1] || 150] });
    } catch (e) { /* skip a broken sprite */ }
  }));
  notify();
}
export const heroArt = (cls) => heroes.get(cls) || null;
export const hasMobArt = (slug) => mobSvg.has(slug);
/** recoloured monster image; returns null until it has loaded (an 'sxs-art' event follows) */
export function mobArt(slug, pal) {
  const svg = mobSvg.get(slug); if (!svg) return null;
  const key = slug + '|' + pal.join('|'), c = mobImg.get(key);
  if (c) return c === 1 ? null : c;
  mobImg.set(key, 1);
  const col = svg.replace(/#b5694a/gi, pal[0]).replace(/#e0a27f/gi, pal[1]).replace(/#7a3f28/gi, pal[2]).replace(/<svg /, '<svg width="400" height="400" ');
  toImg(col).then((im) => { if (im) { mobImg.set(key, im); notify(); } else mobImg.delete(key); });
  return null;
}
